import { handwritingFont, handwritingProfile, wrapHandwriting } from './siteHandwriting.js';
const PLACEMENTS = [
  { x:115, y:165, width:730, height:145, size:63, angle:-.038, opacity:.82 },
  { x:285, y:385, width:575, height:105, size:67, angle:.027, opacity:.66 },
  { x:135, y:565, width:705, height:135, size:55, angle:-.018, opacity:.75 },
  { x:220, y:790, width:650, height:145, size:49, angle:.031, opacity:.62 },
  { x:120, y:1010, width:730, height:130, size:41, angle:-.026, opacity:.7 },
];

// These are inscriptions taken only from the public collection. Keep each
// question complete, with no links, suggested prompts or invented questions.
export function museumPageQuestions(views=[]) {
  return [...new Set(views.map(view=>String(view.question||'').trim()).filter(text=>text && [...text].length<=160))].slice(0,PLACEMENTS.length);
}

export function paintMuseumQuestionPage(context, questions, ink) {
  context.clearRect(0,0,1000,1250);
  questions.forEach((question,index)=>{
    const place=PLACEMENTS[index];
    if(!place)return;
    let size=place.size,lines;
    do{
      context.font=handwritingFont(size,question);
      lines=wrapHandwriting(context,question,place.width);
      if(lines.length*size*1.35<=place.height)break;
      size*=.94;
    }while(size>1);
    context.save();
    context.translate(place.x,place.y);context.rotate(place.angle);
    context.fillStyle=ink;context.globalAlpha=place.opacity;
    context.textBaseline='top';context.direction=handwritingProfile(question).direction;context.textAlign=context.direction==='rtl'?'right':'left';
    lines.forEach((line,i)=>context.fillText(line,context.direction==='rtl'?place.width:0,i*size*1.35));
    context.restore();
  });
}
