import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

export const OVERVIEW_LIMITS = Object.freeze({
  minDistance: 36,
  maxDistance: 95,
  minPolarAngle: Math.PI / 18,
  maxPolarAngle: Math.PI * .46,
  maxTargetRadius: 6,
});

export function createMuseumOverviewControls(camera, element, target, invalidate) {
  const controls = new OrbitControls(camera, element);
  Object.assign(controls, OVERVIEW_LIMITS, {
    enableDamping: true, dampingFactor: .12,
    rotateSpeed: .65, zoomSpeed: .8, panSpeed: .55,
    screenSpacePanning: false,
  });
  controls.target.fromArray(target);
  controls.cursor.copy(controls.target);
  const grab = () => { element.style.cursor = 'var(--site-grab-cursor,grab)'; };
  const start = () => { element.style.cursor = 'var(--site-grabbing-cursor,grabbing)'; invalidate(); };
  controls.addEventListener('change', invalidate);
  controls.addEventListener('start', start);
  controls.addEventListener('end', grab);
  controls.update();
  grab();
  return controls;
}
