// Ordinary visits share a walking pace. Turning still needs time when two
// nearby displays face in different directions. The architectural overview
// has its own deliberately paced camera move.
export const MUSEUM_WALK_MAX_SECONDS = 2.2;

export function museumTravelDuration(distance, turn = 0, overview = false) {
  if (overview) return 2.4;
  return Math.min(MUSEUM_WALK_MAX_SECONDS, Math.max(.28, Math.max(0, distance) / 4.6, Math.abs(turn) / 1.8));
}

// A walking camera keeps its horizon level. Interpolate the two viewing
// angles independently so an elevated destination cannot introduce roll.
export function museumTravelRotation(from, to, progress) {
  const turn = Math.atan2(Math.sin(to.yaw-from.yaw), Math.cos(to.yaw-from.yaw));
  return {
    yaw: from.yaw + turn * progress,
    pitch: from.pitch + (to.pitch-from.pitch) * progress,
  };
}


// The side view is introduced from the familiar entrance-facing position.
// A frontal arrival begins behind that position and advances into the hall.
export function museumHallOpeningPose(destination, front, {arriving=false, across=false, reducedMotion=false}={}) {
  const animate=arriving&&!reducedMotion;
  const pose=animate?front:destination;
  const eye=[...pose.eye];
  if(animate&&!across)eye[2]+=12;
  return {eye,look:[...pose.look]};
}
