// Keep one still frame over the live canvas while the next view appears.
// Copy immediately after rendering so WebGL needs no persistent draw buffer.
export function createMuseumSceneDissolve(host, source, render) {
  let active = null;
  function cancel() {
    active?.animation?.cancel();
    active?.layer.remove();
    active = null;
  }
  async function run(changeView, { duration = 800 } = {}) {
    cancel();
    const layer = source.ownerDocument.createElement('canvas');
    const scale = Math.min(1, 1600 / Math.max(source.width, source.height));
    layer.width = Math.max(1, Math.round(source.width * scale));
    layer.height = Math.max(1, Math.round(source.height * scale));
    const context = layer.getContext('2d');
    if (!context) {
      changeView();
      render();
      return true;
    }
    render();
    context.drawImage(source, 0, 0, layer.width, layer.height);
    layer.setAttribute('aria-hidden', 'true');
    layer.className = 'museum-scene-dissolve';
    Object.assign(layer.style, { position: 'absolute', inset: '0', width: '100%', height: '100%', pointerEvents: 'none' });
    host.appendChild(layer);
    const transition = { layer, animation: null };
    active = transition;
    try {
      changeView();
      render();
      transition.animation = layer.animate([
        { opacity: 1 },
        { opacity: 0, offset: .8 },
        { opacity: 0 },
      ], { duration, easing: 'ease-in-out', fill: 'forwards' });
      await transition.animation.finished;
      return active === transition;
    } catch {
      return false;
    } finally {
      layer.remove();
      if (active === transition) active = null;
    }
  }
  return { run, cancel };
}
